package warehouse.mas;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Config {

    // Model-driven control layer. These records are generated from
    // WarehouseController, Task, and Product elements and use the same stable
    // Robot{n}/... OPC UA prefixes as the Isaac Sim bridge.
    public static final String NODE_LOCATION = "Location";
    public static final String NODE_TARGET = "Target";
    public static final String NODE_STATE = "State";
    public static final String NODE_HAS_PRODUCT = "HasProduct";
    public static final String NODE_BATTERY_LEVEL = "BatteryLevel";

    public static String robotNodeId(String robotId, String leaf) {
        return robotId + "/" + leaf;
    }

    public static final class ControllerSpec {
        public final String id;
        public final String name;
        public final String dispatchPolicy;
        public final int updateIntervalMs;
        public final String[] controlledRobots;
        public final String[] monitoredConveyors;

        ControllerSpec(String id, String name, String dispatchPolicy, int updateIntervalMs,
                       String[] controlledRobots, String[] monitoredConveyors) {
            this.id = id;
            this.name = name;
            this.dispatchPolicy = dispatchPolicy;
            this.updateIntervalMs = updateIntervalMs;
            this.controlledRobots = controlledRobots;
            this.monitoredConveyors = monitoredConveyors;
        }
    }

    public static final class TaskSpec {
        public final String id;
        public final String name;
        public final String status;
        public final int priority;
        public final String assignedRobot;
        public final String pickup;
        public final String dropoff;

        TaskSpec(String id, String name, String status, int priority,
                 String assignedRobot, String pickup, String dropoff) {
            this.id = id;
            this.name = name;
            this.status = status;
            this.priority = priority;
            this.assignedRobot = assignedRobot;
            this.pickup = pickup;
            this.dropoff = dropoff;
        }
    }

    public static final class ProductSpec {
        public final String id;
        public final String name;
        public final String sku;
        public final double weightKg;
        public final String locatedAt;

        ProductSpec(String id, String name, String sku, double weightKg, String locatedAt) {
            this.id = id;
            this.name = name;
            this.sku = sku;
            this.weightKg = weightKg;
            this.locatedAt = locatedAt;
        }
    }

    private static List<ControllerSpec> buildControllers() {
        List<ControllerSpec> values = new ArrayList<>();
{{#each elementsByClassName.WarehouseController}}
        values.add(new ControllerSpec(
            {{javaString controlId}},
            {{javaString name}},
            {{javaString DispatchPolicy}},
            {{UpdateInterval}},
            new String[] { {{#each resolvedReferences.controls}}{{javaString opcNodeId}}{{#unless @last}}, {{/unless}}{{/each}} },
            new String[] { {{#each resolvedReferences.monitors}}{{javaString opcNodeId}}{{#unless @last}}, {{/unless}}{{/each}} }
        ));
{{/each}}
        return values;
    }

    private static List<TaskSpec> buildTasks() {
        List<TaskSpec> values = new ArrayList<>();
{{#each elementsByClassName.Task}}
        values.add(new TaskSpec(
            {{javaString taskId}},
            {{javaString name}},
            {{javaString Status}},
            {{Priority}},
            {{javaString resolvedReferences.assignedTo.opcNodeId}},
            {{javaString resolvedReferences.pickup.name}},
            {{javaString resolvedReferences.dropoff.name}}
        ));
{{/each}}
        return values;
    }

    private static List<ProductSpec> buildProducts() {
        List<ProductSpec> values = new ArrayList<>();
{{#each elementsByClassName.Product}}
        values.add(new ProductSpec(
            {{javaString productId}},
            {{javaString name}},
            {{javaString Sku}},
            {{WeightKg}},
            {{javaString resolvedReferences.locatedAt.name}}
        ));
{{/each}}
        return values;
    }

    public static final List<ControllerSpec> CONTROLLERS = buildControllers();
    public static final List<TaskSpec> TASKS = buildTasks();
    public static final List<ProductSpec> PRODUCTS = buildProducts();

    // OPC-UA Server Configuration - bunun testi yazılacak
    public static final String SERVER_NAME = "{{WarehouseModel.WarehouseMAS.name}}";
    public static final int SERVER_PORT = {{WarehouseModel.WarehouseMAS.OpcuaServerPort}};
    public static final String NAMESPACE_URI = "{{WarehouseModel.WarehouseMAS.NamespaceURI}}";

    // Robot Configuration - Dynamic list
    public static final List<String> ROBOT_NAMES = new ArrayList<String>() \{{
        {{#range 1 countByClassName.MobileRobot}}
        add("Robot{{this}}");
        {{/range}}
    }};

    // Conveyor Configuration - Dynamic list
    public static final List<String> CONVEYOR_NAMES = new ArrayList<String>() \{{
        {{#range 1 countByClassName.Conveyor}}
        add("Conveyor{{this}}");
        {{/range}}
    }};

    // Location Coordinates (X, Y, Z in mm) - Loaded from JSON files
    public static final List<double[]> CONVEYOR_LOCATIONS_LIST = loadCoordinates("ConveyorLocation.json");
    public static final List<double[]> CHARGING_STATIONS = loadCoordinates("ChargingStationLocation.json");
    public static final double[] LOC_OUTPUT = loadSingleCoordinate("OutputLocation.json");
    public static final double[] LOC_IDLE = {1000, 0, 0};

    // Conveyor locations - Dynamic map
    public static final Map<String, double[]> CONVEYOR_LOCATIONS = buildConveyorMap();

    // All pickup/delivery locations - Dynamic list
    public static final List<double[]> TASK_LOCATIONS = new ArrayList<>(CONVEYOR_LOCATIONS_LIST);

    // Battery Management
    public static final int INITIAL_BATTERY = {{lookup (lookup WarehouseModel "Mobile Robot Resource") "BatteryLevel"}};
    public static final int LOW_BATTERY_THRESHOLD = {{lookup (lookup WarehouseModel "Mobile Robot Resource") "LowBatteryThreshold"}};
    public static final int CHARGE_RATE = {{lookup (lookup WarehouseModel "Mobile Robot Resource") "ChargeRate"}};

    // Agent Update Interval
    public static final int UPDATE_INTERVAL = {{WarehouseModel.WarehouseMAS.UpdateInterval}};

    // JADE Service Names
    public static final String YELLOW_PAGES_SERVICE = "warehouse-robot";
    public static final String COORDINATOR_SERVICE = "warehouse-coordinator";

    // Initial Positions JSON Files
    private static final String POSITIONS_DIR = "positions/";
    private static final Map<String, String> POSITION_FILES = new HashMap<String, String>() \{{
        put("Robot", "RobotLocation.json");
        put("ChargingStation", "ChargingStationLocation.json");
        put("Conveyor", "ConveyorLocation.json");
        put("PathwayArea", "PathwayAreaLocation.json");
        put("OutputLocation", "OutputLocation.json");
    }};

    // Load coordinates from JSON file
    private static List<double[]> loadCoordinates(String filename) {
        List<double[]> coords = new ArrayList<>();
        try {
            String json = new String(Files.readAllBytes(Paths.get(POSITIONS_DIR + filename)));
            Pattern pattern = Pattern.compile("\"X\"\\s*:\\s*([+-]?\\d+\\.?\\d*)[^}]*\"Y\"\\s*:\\s*([+-]?\\d+\\.?\\d*)");
            Matcher matcher = pattern.matcher(json);
            while (matcher.find()) {
                double x = Double.parseDouble(matcher.group(1));
                double y = Double.parseDouble(matcher.group(2));
                coords.add(new double[]{x, y, 0});
            }
        } catch (Exception e) {
            System.err.println("Error loading " + filename + ": " + e.getMessage());
        }
        return coords;
    }

    // Load single coordinate (first entry from JSON file)
    private static double[] loadSingleCoordinate(String filename) {
        List<double[]> coords = loadCoordinates(filename);
        return coords.isEmpty() ? new double[]{0, 0, 0} : coords.get(0);
    }

    // Build conveyor map dynamically from CONVEYOR_NAMES and loaded coordinates
    private static Map<String, double[]> buildConveyorMap() {
        Map<String, double[]> map = new HashMap<>();
        for (int i = 0; i < Math.min(CONVEYOR_NAMES.size(), CONVEYOR_LOCATIONS_LIST.size()); i++) {
            map.put(CONVEYOR_NAMES.get(i), CONVEYOR_LOCATIONS_LIST.get(i));
        }
        return map;
    }

    // Load InitialPositions from JSON file
    public static String loadInitialPositions(String componentType) throws IOException {
        String filename = POSITION_FILES.get(componentType);
        return new String(Files.readAllBytes(Paths.get(POSITIONS_DIR + filename))).replaceAll("\\s+", " ");
    }

    // Dynamic Configuration Methods
    public static void addRobot(String robotName) {
        if (!ROBOT_NAMES.contains(robotName)) {
            ROBOT_NAMES.add(robotName);
        }
    }

    public static void addConveyor(String conveyorName) {
        if (!CONVEYOR_NAMES.contains(conveyorName)) {
            CONVEYOR_NAMES.add(conveyorName);
        }
    }

    public static void addConveyorLocation(String conveyorName, double[] location) {
        CONVEYOR_LOCATIONS.put(conveyorName, location);
    }

    public static void addTaskLocation(double[] location) {
        TASK_LOCATIONS.add(location);
    }

    public static void addChargingStation(double[] location) {
        CHARGING_STATIONS.add(location);
    }
}
